<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { ElMessage, ElMessageBox } from 'element-plus';
import http from '../api/http';
import { useAuthStore } from '../stores/auth';

const route = useRoute();
const mode = computed(() => String(route.path.split('/').pop()));
const title = computed(() => ({ sessions: '门诊班次', templates: '排班模板', calendar: '排班工作台' }[mode.value] ?? '排班中心'));
const rows = ref<Record<string, any>[]>([]), loading = ref(false), error = ref('');
const master = reactive<Record<string, any[]>>({ doctors: [], campuses: [], outpatientDepartments: [], sessions: [], rooms: [] });
const editor = ref(false), detail = ref(false), roomDialog = ref(false), selected = ref<Record<string, any> | null>(null), previewRows = ref<Record<string, any>[]>([]), roomId = ref<number>();
const filter = reactive({ doctorId: undefined as number | undefined, campusId: undefined as number | undefined, from: '', to: '' });
const form = reactive<Record<string, any>>({});
const auth = useAuthStore();
const can = (permission: string) => auth.session?.permissions.includes(permission) ?? false;
const availableRooms = computed(() => master.rooms.filter(room => Number(room.status) === 1 && (!selected.value || (Number(room.campusId) === Number(selected.value.campusId) && Number(room.outpatientDepartmentId) === Number(selected.value.outpatientDepartmentId)))));
function reset(row?: Record<string, any>) {
  Object.keys(form).forEach(key => delete form[key]);
  if (mode.value === 'sessions') Object.assign(form, { code: row?.code ?? '', name: row?.name ?? '', startTime: row?.startTime ?? '08:00:00', endTime: row?.endTime ?? '12:00:00', sortOrder: row?.sortOrder ?? 0, status: row?.status ?? true, version: row?.version ?? 0, hospitalId: row?.hospitalId ?? 1 });
  if (mode.value === 'templates') Object.assign(form, { code: row?.templateCode ?? '', name: row?.name ?? '', doctorId: row?.doctorId, campusId: row?.campusId, outpatientDepartmentId: row?.outpatientDepartmentId, validFrom: row?.validFrom ?? '', validTo: row?.validTo ?? '', quotaPerSession: row?.quotaPerSession ?? 20, status: row?.status ?? true, published: row?.published ?? true, rules: row?.rules ?? [], version: row?.version ?? 0 });
  if (mode.value === 'calendar') Object.assign(form, { doctorId: row?.doctorId, campusId: row?.campusId, outpatientDepartmentId: row?.outpatientDepartmentId, date: row?.scheduleDate ?? '', sessionDefinitionId: row?.sessionDefinitionId, startTime: row?.startTime ?? '08:00:00', endTime: row?.endTime ?? '12:00:00', totalQuota: row?.totalQuota ?? 20, source: 'MANUAL', slotMode: false });
}
async function loadMaster() { const sources: Array<[string, string, Record<string, any>?]> = [['doctors', '/admin/master/doctors', { page: 1, pageSize: 100 }], ['campuses', '/admin/master/campuses'], ['outpatientDepartments', '/admin/master/outpatient-departments'], ['sessions', '/admin/schedule/sessions'], ['rooms', '/admin/clinic-rooms']]; await Promise.all(sources.map(async ([key, url, params]) => { try { const data = (await http.get(url, { params })).data.data; master[key] = Array.isArray(data) ? data : data.records ?? []; } catch { master[key] = []; } })); }
async function load() { loading.value = true; error.value = ''; try { const endpoint = mode.value === 'sessions' ? '/admin/schedule/sessions' : mode.value === 'templates' ? '/admin/schedule/templates' : '/admin/schedules'; const response = await http.get(endpoint, { params: mode.value === 'calendar' ? { ...filter, page: 1, pageSize: 100 } : undefined }); const data = response.data.data; rows.value = Array.isArray(data) ? data : data.records ?? []; } catch (reason: any) { error.value = reason.response?.data?.message ?? '加载排班数据失败'; } finally { loading.value = false; } }
function open(row?: Record<string, any>) { reset(row); selected.value = row ?? null; previewRows.value = []; editor.value = true; }
function numericPayload() { const value = { ...form }; for (const key of ['doctorId', 'campusId', 'outpatientDepartmentId', 'sessionDefinitionId', 'totalQuota', 'quotaPerSession', 'hospitalId', 'sortOrder']) if (value[key] !== undefined && value[key] !== null && value[key] !== '') value[key] = Number(value[key]); return value; }
async function save() { try { const payload = numericPayload(); if (mode.value === 'sessions') { if (selected.value) await http.put(`/admin/schedule/sessions/${selected.value.id}`, payload); else await http.post('/admin/schedule/sessions', payload); } if (mode.value === 'templates') { if (selected.value) await http.put(`/admin/schedule/templates/${selected.value.id}`, payload); else await http.post('/admin/schedule/templates', payload); } if (mode.value === 'calendar') await http.post('/admin/schedules', payload); ElMessage.success('已保存'); editor.value = false; await load(); } catch (reason: any) { ElMessage.error(reason.response?.data?.message ?? '保存失败'); } }
function addRule() { form.rules.push({ dayOfWeek: 1, sessionDefinitionId: master.sessions[0]?.id, sortOrder: form.rules.length }); }
async function preview() { try { previewRows.value = (await http.post(`/admin/schedule/templates/${selected.value?.id ?? 0}/preview`, { from: form.validFrom, to: form.validTo })).data.data; } catch (reason: any) { ElMessage.error(reason.response?.data?.message ?? '预览失败'); } }
async function generate(row: Record<string, any>) { try { const result = (await http.post(`/admin/schedule/templates/${row.id}/generate`, { from: row.validFrom, to: row.validTo })).data.data; ElMessage.success(`已生成 ${result.length} 条排班；重复日期会自动跳过`); await load(); } catch (reason: any) { ElMessage.error(reason.response?.data?.message ?? '生成失败'); } }
async function inspect(row: Record<string, any>) { selected.value = row; detail.value = true; }
async function action(action: string) { if (!selected.value) return; try { const version = selected.value.version; if (action === 'publish') await http.post(`/admin/schedules/${selected.value.id}/publish`, { version }); if (action === 'stop') { const { value } = await ElMessageBox.prompt('请输入停诊原因', '确认停诊', { inputValue: '排班调整' }); await http.post(`/admin/schedules/${selected.value.id}/stop`, { reasonCode: 'ADMIN', reason: value, version }); } if (action === 'quota') { const { value } = await ElMessageBox.prompt('请输入调整后的总号源', '号源调整', { inputValue: String(selected.value.totalQuota) }); await http.post(`/admin/schedules/${selected.value.id}/quota`, { totalQuota: Number(value), reason: '工作台调整', version }); } if (action === 'substitute') { const { value } = await ElMessageBox.prompt('请输入替诊医生 ID', '替诊', { inputPattern: /^\d+$/, inputErrorMessage: '请输入数字 ID' }); await http.post(`/admin/schedules/${selected.value.id}/substitute`, { doctorId: Number(value), reason: '工作台替诊', version }); } if (action === 'slots') { const { value } = await ElMessageBox.prompt('请输入每个号段分钟数', '自动切分号段', { inputValue: '30', inputPattern: /^\d+$/, inputErrorMessage: '请输入正整数' }); await http.post(`/admin/schedules/${selected.value.id}/slots/generate`, { durationMinutes: Number(value), quota: Math.floor(selected.value.totalQuota / 4) }); } ElMessage.success('操作已完成'); detail.value = false; await load(); } catch (reason: any) { if (reason !== 'cancel' && reason !== 'close') ElMessage.error(reason.response?.data?.message ?? '操作失败'); } }
function openRoom(){roomId.value=selected.value?.clinicRoomId;roomDialog.value=true;}
async function saveRoom(){if(!selected.value||!roomId.value)return;try{await http.post(`/admin/clinic-rooms/${roomId.value}/assign-schedule/${selected.value.id}`,{version:selected.value.version});ElMessage.success('诊室分配已保存');roomDialog.value=false;detail.value=false;await load();}catch(reason:any){ElMessage.error(reason.response?.data?.message??'诊室分配失败');}}
watch(mode, async () => { await loadMaster(); await load(); }); onMounted(async () => { await loadMaster(); await load(); });
</script>
<template>
  <section class="workbench"><div class="toolbar"><div><h2>{{ title }}</h2><p>{{ mode === 'calendar' ? '覆盖创建、发布、停诊、替诊、号段和号源调整的真实排班工作台。' : '全部数据均来自排班中心服务。' }}</p></div><div><el-button @click="load">刷新</el-button><el-button v-if="can(mode === 'sessions' ? 'hospital:schedule-session:manage' : mode === 'templates' ? 'hospital:schedule-template:manage' : 'hospital:schedule:create')" type="primary" @click="open()">{{ mode === 'calendar' ? '手工新增排班' : '新建' }}</el-button></div></div>
  <el-form v-if="mode === 'calendar'" class="filters" inline><el-form-item label="医生"><el-select v-model="filter.doctorId" clearable filterable><el-option v-for="x in master.doctors" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item><el-form-item label="院区"><el-select v-model="filter.campusId" clearable><el-option v-for="x in master.campuses" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item><el-form-item label="起止日期"><el-date-picker v-model="filter.from" value-format="YYYY-MM-DD"/><span>至</span><el-date-picker v-model="filter.to" value-format="YYYY-MM-DD"/></el-form-item><el-button @click="load">查询</el-button></el-form>
  <el-alert v-if="error" :title="error" type="error" show-icon/><el-skeleton v-else-if="loading" :rows="5" animated/><el-empty v-else-if="!rows.length" description="暂无排班数据，可从这里开始建立"/><el-table v-else :data="rows" @row-click="mode === 'calendar' ? inspect($event) : undefined"><template v-if="mode === 'sessions'"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="班次名称"/><el-table-column prop="startTime" label="开始"/><el-table-column prop="endTime" label="结束"/><el-table-column label="操作"><template #default="scope"><el-button v-if="can('hospital:schedule-session:manage')" link type="primary" @click.stop="open(scope.row)">编辑</el-button></template></el-table-column></template><template v-else-if="mode === 'templates'"><el-table-column prop="templateCode" label="模板编码"/><el-table-column prop="name" label="模板名称"/><el-table-column prop="validFrom" label="生效开始"/><el-table-column prop="validTo" label="生效结束"/><el-table-column prop="quotaPerSession" label="每班号源"/><el-table-column label="操作"><template #default="scope"><el-button link type="primary" @click="open(scope.row)">编辑/预览</el-button><el-button v-if="can('hospital:schedule-template:manage')" link type="success" @click="generate(scope.row)">生成</el-button></template></el-table-column></template><template v-else><el-table-column prop="scheduleDate" label="日期"/><el-table-column prop="startTime" label="时段"/><el-table-column prop="doctorName" label="出诊医生"/><el-table-column prop="departmentName" label="医疗科室"/><el-table-column prop="sessionName" label="班次"/><el-table-column label="可用/总号源"><template #default="scope">{{ scope.row.availableQuota }} / {{ scope.row.totalQuota }}</template></el-table-column><el-table-column prop="scheduleStatus" label="状态"/><el-table-column prop="source" label="来源"/><el-table-column label="操作"><template #default="scope"><el-button link type="primary" @click.stop="inspect(scope.row)">详情与操作</el-button></template></el-table-column></template></el-table>
  <el-dialog v-model="editor" :title="selected ? '编辑' : (mode === 'calendar' ? '手工新增排班' : '新建' + title)" width="700px"><el-form label-position="top"><template v-if="mode === 'sessions'"><el-form-item label="医院 ID"><el-input-number v-model="form.hospitalId" :min="1"/></el-form-item><el-form-item label="编码"><el-input v-model="form.code" :disabled="!!selected"/></el-form-item><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="时间"><el-time-picker v-model="form.startTime" value-format="HH:mm:ss"/><span>至</span><el-time-picker v-model="form.endTime" value-format="HH:mm:ss"/></el-form-item></template><template v-else-if="mode === 'templates'"><el-form-item label="模板编码"><el-input v-model="form.code" :disabled="!!selected"/></el-form-item><el-form-item label="模板名称"><el-input v-model="form.name"/></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="医生"><el-select v-model="form.doctorId" filterable><el-option v-for="x in master.doctors" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="院区"><el-select v-model="form.campusId"><el-option v-for="x in master.campuses" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item></el-col></el-row><el-form-item label="门诊科室"><el-select v-model="form.outpatientDepartmentId"><el-option v-for="x in master.outpatientDepartments" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item><el-form-item label="有效日期"><el-date-picker v-model="form.validFrom" value-format="YYYY-MM-DD"/><span>至</span><el-date-picker v-model="form.validTo" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="每班号源"><el-input-number v-model="form.quotaPerSession" :min="0"/></el-form-item><el-divider>适用规则</el-divider><div v-for="(rule,index) in form.rules" :key="index" class="rule"><el-select v-model="rule.dayOfWeek"><el-option v-for="i in 7" :key="i" :value="i" :label="'星期' + '一二三四五六日'[i-1]"/></el-select><el-select v-model="rule.sessionDefinitionId"><el-option v-for="x in master.sessions" :key="x.id" :value="x.id" :label="x.name"/></el-select><el-button link type="danger" @click="form.rules.splice(index,1)">删除</el-button></div><el-button link type="primary" @click="addRule">添加规则</el-button></template><template v-else><el-row :gutter="12"><el-col :span="12"><el-form-item label="医生"><el-select v-model="form.doctorId" filterable><el-option v-for="x in master.doctors" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="院区"><el-select v-model="form.campusId"><el-option v-for="x in master.campuses" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item></el-col></el-row><el-form-item label="门诊科室"><el-select v-model="form.outpatientDepartmentId"><el-option v-for="x in master.outpatientDepartments" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item><el-form-item label="日期与班次"><el-date-picker v-model="form.date" value-format="YYYY-MM-DD"/><el-select v-model="form.sessionDefinitionId"><el-option v-for="x in master.sessions" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item><el-form-item label="开始/结束"><el-time-picker v-model="form.startTime" value-format="HH:mm:ss"/><el-time-picker v-model="form.endTime" value-format="HH:mm:ss"/></el-form-item><el-form-item label="总号源"><el-input-number v-model="form.totalQuota" :min="0"/></el-form-item></template></el-form><el-table v-if="previewRows.length" :data="previewRows" size="small"><el-table-column prop="date" label="预览日期"/><el-table-column prop="sessionDefinitionId" label="班次 ID"/></el-table><template #footer><el-button v-if="mode === 'templates' && selected" @click="preview">预览生成结果</el-button><el-button @click="editor=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
  <el-dialog v-model="detail" title="排班详情与操作" width="720px"><el-descriptions v-if="selected" :column="2" border><el-descriptions-item label="日期">{{ selected.scheduleDate }}</el-descriptions-item><el-descriptions-item label="状态">{{ selected.scheduleStatus }}</el-descriptions-item><el-descriptions-item label="医生">{{ selected.doctorName }}</el-descriptions-item><el-descriptions-item label="号源">{{ selected.availableQuota }} / {{ selected.totalQuota }}</el-descriptions-item><el-descriptions-item label="时段">{{ selected.startTime }} - {{ selected.endTime }}</el-descriptions-item><el-descriptions-item label="诊室">{{ selected.clinicRoomName ? `${selected.clinicRoomCode} · ${selected.clinicRoomName}（${selected.clinicRoomNumber}）` : '未分配' }}</el-descriptions-item></el-descriptions><el-divider>操作</el-divider><el-space wrap><el-button v-if="can('hospital:clinic-room:manage')" @click="openRoom">分配诊室</el-button><el-button v-if="selected?.scheduleStatus==='DRAFT' && can('hospital:schedule:publish')" type="success" @click="action('publish')">发布</el-button><el-button v-if="['DRAFT','PUBLISHED'].includes(selected?.scheduleStatus) && can('hospital:schedule:stop')" type="danger" @click="action('stop')">停诊</el-button><el-button v-if="can('hospital:schedule:substitute')" @click="action('substitute')">替诊</el-button><el-button v-if="can('hospital:schedule:quota')" @click="action('quota')">调整号源</el-button><el-button v-if="can('hospital:schedule:update')" @click="action('slots')">自动切分号段</el-button></el-space><el-divider>号段</el-divider><el-table :data="selected?.slots ?? []" size="small"><el-table-column prop="startTime" label="开始"/><el-table-column prop="endTime" label="结束"/><el-table-column prop="availableQuota" label="可用号源"/></el-table></el-dialog><el-dialog v-model="roomDialog" title="分配排班诊室" width="520px"><p>仅显示当前排班院区、门诊科室下真实启用的诊室；保存后候诊、前台与医生工作台会读取同一诊室关系。</p><el-select v-model="roomId" filterable style="width:100%"><el-option v-for="room in availableRooms" :key="room.id" :value="room.id" :label="`${room.roomCode} · ${room.roomName} · ${room.roomNumber} · 楼宇#${room.buildingId} · 楼层#${room.floorId} · 门诊科室#${room.outpatientDepartmentId} · 启用`"/></el-select><template #footer><el-button @click="roomDialog=false">取消</el-button><el-button type="primary" :disabled="!roomId" @click="saveRoom">保存诊室</el-button></template></el-dialog></section>
</template>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.toolbar h2{margin:0}.toolbar p{color:#718096;margin:6px 0 0}.filters{padding:14px;background:#f8fafc;margin-bottom:16px}.rule{display:flex;gap:8px;margin:8px 0}.rule .el-select{width:220px}</style>
